CREATE TABLE "SocialMunicipalSettings" (id TEXT PRIMARY KEY CHECK (id='municipal'), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), parameters JSONB NOT NULL CHECK(jsonb_typeof(parameters)='object'), "updatedBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialImportLayout" (id TEXT PRIMARY KEY, name TEXT NOT NULL, version TEXT NOT NULL, configuration JSONB NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialImportLayout_name_version_key" ON "SocialImportLayout"(name,version);
CREATE TABLE "SocialCadastreSnapshot" (cpf TEXT PRIMARY KEY, "personId" TEXT NOT NULL REFERENCES "Person"(id), "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), nis TEXT, name TEXT NOT NULL, "familyCode" TEXT NOT NULL, "perCapitaIncome" NUMERIC(14,2) NOT NULL CHECK("perCapitaIncome">=0), composition INTEGER NOT NULL CHECK(composition>0), address TEXT, municipality TEXT NOT NULL, uf TEXT NOT NULL, "batchId" TEXT NOT NULL REFERENCES "SocialImportBatch"(id), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialCadastreSnapshot_nis_key" ON "SocialCadastreSnapshot"(nis);
CREATE TABLE "SocialCaseFile" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "familyId" TEXT REFERENCES "SocialFamily"(id), "personId" TEXT REFERENCES "Person"(id), "professionalId" TEXT NOT NULL REFERENCES "Employee"(id), "receivedAt" DATE NOT NULL, "enteredVia" TEXT NOT NULL, "initialDemand" TEXT NOT NULL, "secrecyLevel" TEXT NOT NULL DEFAULT 'Normal' CHECK("secrecyLevel" IN ('Normal','Restrito','CREAS')), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')), "modelVersion" TEXT NOT NULL, sections JSONB NOT NULL CHECK(jsonb_typeof(sections)='object'), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(("familyId" IS NULL)<>("personId" IS NULL)));
CREATE INDEX "SocialCaseFile_subject_unit_idx" ON "SocialCaseFile"("unitId","familyId","personId");
CREATE UNIQUE INDEX "SocialCaseFile_active_family_key" ON "SocialCaseFile"("unitId","familyId") WHERE status='ACTIVE' AND "familyId" IS NOT NULL;
CREATE UNIQUE INDEX "SocialCaseFile_active_person_key" ON "SocialCaseFile"("unitId","personId") WHERE status='ACTIVE' AND "personId" IS NOT NULL;
CREATE TABLE "SocialVisitAttendance" ("visitId" TEXT PRIMARY KEY REFERENCES "SocialVisit"(id), "attendanceId" TEXT NOT NULL REFERENCES "SocialAttendance"(id), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialVisitAttendance_attendance_key" ON "SocialVisitAttendance"("attendanceId");
CREATE TABLE "SocialMonthlyStatement" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), competence TEXT NOT NULL CHECK(competence ~ '^\d{4}-(0[1-9]|1[0-2])$'), "professionalId" TEXT NOT NULL REFERENCES "Employee"(id), status TEXT NOT NULL CHECK(status IN ('DRAFT','FINAL')), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), "declaredValues" JSONB NOT NULL, observations TEXT NOT NULL, snapshot JSONB NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialMonthlyStatement_unit_competence_key" ON "SocialMonthlyStatement"("unitId",competence);
CREATE TABLE "SocialIssuedDocument" (id TEXT PRIMARY KEY, "unitId" TEXT NOT NULL REFERENCES "SocialUnit"(id), "familyId" TEXT REFERENCES "SocialFamily"(id), "personId" TEXT REFERENCES "Person"(id), "templateCode" TEXT NOT NULL, model JSONB NOT NULL, "values" JSONB NOT NULL, status TEXT NOT NULL CHECK(status IN ('DRAFT','ISSUED')), "issuedAt" TIMESTAMP(3), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SocialMessageDispatch" (id TEXT PRIMARY KEY, "messageId" TEXT NOT NULL REFERENCES "SocialMessage"(id), provider TEXT NOT NULL, "parametersRevision" INTEGER NOT NULL, configuration JSONB NOT NULL, state TEXT NOT NULL CHECK(state IN ('DISPATCHING','ACCEPTED','SENT','DELIVERED','FAILED','UNKNOWN')), "externalId" TEXT, error TEXT, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SocialMessageDispatch_message_key" ON "SocialMessageDispatch"("messageId");
CREATE INDEX "SocialMessageDispatch_created_idx" ON "SocialMessageDispatch"("createdAt");
-- Private provenance ledger for explicitly reviewed presentation corrections.
-- Signed documents, identities and audit events are never rewritten by this operation.
CREATE TABLE "MunicipalPresentationRevision" (id TEXT PRIMARY KEY, "tableName" TEXT NOT NULL, "recordId" TEXT NOT NULL, "columnName" TEXT NOT NULL, "previousValue" TEXT, "currentValue" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
